</head><body class="fw-controls-v3"><main class="fw-auth-form-side" style="min-height:100vh"><div class="fw-auth-form-wrap"><div class="fw-auth-kicker">ACCOUNT RECOVERY</div><h1 class="h2">Reset your password</h1><p class="fw-auth-intro">Use the recovery code you saved from registration or Settings. This code is secret and works once. Fundwise does not currently send reset emails.</p><?php if($message!==''):?><div class="alert alert-danger" role="alert"><?= htmlspecialchars($message,ENT_QUOTES,'UTF-8') ?></div><?php endif;?><form method="post"><input type="hidden" name="fw_request_token" value="<?= htmlspecialchars(fw_request_token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'],ENT_QUOTES,'UTF-8') ?>"><div class="fw-auth-field"><label for="recoveryEmail">Account email</label><input id="recoveryEmail" type="email" name="email" class="form-control" required autocomplete="username"></div><div class="fw-auth-field"><label for="recoveryCode">Recovery code</label><div class="fw-password-wrap"><input id="recoveryCode" type="password" name="recovery_code" class="form-control" required autocomplete="off" maxlength="64"><button type="button" class="fw-password-btn" data-fw-password-toggle="recoveryCode" aria-label="Show password" title="Show password"><i class="bi bi-eye-slash" aria-hidden="true"></i></button></div></div><div class="fw-auth-field"><label for="newPassword">New password</label><div class="fw-password-wrap"><input id="newPassword" type="password" name="new_password" class="form-control" required minlength="8" maxlength="72" autocomplete="new-password"><button type="button" class="fw-password-btn" data-fw-password-toggle="newPassword" aria-label="Show password" title="Show password"><i class="bi bi-eye-slash" aria-hidden="true"></i></button></div></div><div class="fw-auth-field"><label for="confirmPassword">Confirm new password</label><div class="fw-password-wrap"><input id="confirmPassword" type="password" name="confirm_password" class="form-control" required minlength="8" maxlength="72" autocomplete="new-password"><button type="button" class="fw-password-btn" data-fw-password-toggle="confirmPassword" aria-label="Show password" title="Show password"><i class="bi bi-eye-slash" aria-hidden="true"></i></button></div></div><button class="btn btn-primary w-100" type="submit">Reset password</button></form><p class="mt-4"><a href="login.php">Back to sign in</a></p></div></main><script src="<?= htmlspecialchars(BASE_URL,ENT_QUOTES,'UTF-8') ?>/js/ui.js?v=20261105-u3"></script></body></html>
